#!/usr/bin/env python3.11
import os
import re
from pathlib import Path
from collections import defaultdict

class PerformanceAnalyzer:
    def __init__(self, src_dir):
        self.src_dir = Path(src_dir)
        self.issues = defaultdict(list)
        
    def analyze_file(self, filepath):
        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()
            lines = content.split('\n')
            
        rel_path = filepath.relative_to(self.src_dir)
        
        # 1. Operações síncronas de I/O (fs.readFileSync, fs.writeFileSync)
        for i, line in enumerate(lines, 1):
            if re.search(r'\.readFileSync\(|\.writeFileSync\(|\.readdirSync\(', line):
                self.issues['sync_io'].append({
                    'file': str(rel_path),
                    'line': i,
                    'code': line.strip(),
                    'severity': 'HIGH'
                })
        
        # 2. JSON.parse/stringify em loops
        for i, line in enumerate(lines, 1):
            if 'JSON.parse' in line or 'JSON.stringify' in line:
                # Verificar se está dentro de um loop (próximas 5 linhas antes)
                context_start = max(0, i-6)
                context = '\n'.join(lines[context_start:i])
                if re.search(r'for\s*\(|while\s*\(|\.map\(|\.forEach\(', context):
                    self.issues['json_in_loop'].append({
                        'file': str(rel_path),
                        'line': i,
                        'code': line.strip(),
                        'severity': 'HIGH'
                    })
        
        # 3. Operações de criptografia síncronas
        for i, line in enumerate(lines, 1):
            if re.search(r'crypto\.(createHash|createCipher|pbkdf2Sync|scryptSync)', line):
                self.issues['sync_crypto'].append({
                    'file': str(rel_path),
                    'line': i,
                    'code': line.strip(),
                    'severity': 'MEDIUM'
                })
        
        # 4. Loops com operações pesadas sem await
        for i, line in enumerate(lines, 1):
            if re.search(r'for\s*\(.*\)\s*{', line):
                # Verificar próximas 20 linhas
                loop_content = '\n'.join(lines[i:min(i+20, len(lines))])
                has_heavy_ops = any([
                    'decrypt' in loop_content,
                    'encrypt' in loop_content,
                    'serialize' in loop_content,
                    'deserialize' in loop_content,
                    'JSON.parse' in loop_content,
                    'JSON.stringify' in loop_content,
                    'Buffer.from' in loop_content and loop_content.count('Buffer.from') > 3
                ])
                has_await = 'await' in loop_content
                
                if has_heavy_ops and not has_await:
                    self.issues['heavy_sync_loop'].append({
                        'file': str(rel_path),
                        'line': i,
                        'code': line.strip(),
                        'severity': 'CRITICAL'
                    })
        
        # 5. Processamento de arrays grandes sem chunking
        for i, line in enumerate(lines, 1):
            if re.search(r'\.map\(|\.filter\(|\.reduce\(|\.forEach\(', line):
                # Verificar se há verificação de tamanho antes
                context_before = '\n'.join(lines[max(0, i-10):i])
                has_length_check = '.length' in context_before and ('if' in context_before or '?' in context_before)
                
                if not has_length_check:
                    self.issues['unbounded_array_ops'].append({
                        'file': str(rel_path),
                        'line': i,
                        'code': line.strip(),
                        'severity': 'MEDIUM'
                    })
        
        # 6. Operações de rede sem timeout
        for i, line in enumerate(lines, 1):
            if re.search(r'fetch\(|axios\.|request\(|query\(', line):
                # Verificar se há timeout configurado nas próximas linhas
                context_after = '\n'.join(lines[i:min(i+5, len(lines))])
                has_timeout = 'timeout' in context_after or 'signal' in context_after
                
                if not has_timeout and 'query(' in line:
                    self.issues['network_no_timeout'].append({
                        'file': str(rel_path),
                        'line': i,
                        'code': line.strip(),
                        'severity': 'HIGH'
                    })
        
        # 7. Regex complexos que podem causar ReDoS
        for i, line in enumerate(lines, 1):
            if 'new RegExp' in line or re.search(r'/.*[+*]{2,}.*/', line):
                self.issues['complex_regex'].append({
                    'file': str(rel_path),
                    'line': i,
                    'code': line.strip(),
                    'severity': 'LOW'
                })
        
        # 8. Operações de buffer grandes
        for i, line in enumerate(lines, 1):
            if re.search(r'Buffer\.alloc\(|Buffer\.allocUnsafe\(|new Uint8Array\(', line):
                # Verificar se o tamanho é dinâmico e grande
                if re.search(r'\.length|\.size|\* \d{4,}', line):
                    self.issues['large_buffer_alloc'].append({
                        'file': str(rel_path),
                        'line': i,
                        'code': line.strip(),
                        'severity': 'MEDIUM'
                    })
    
    def analyze_all(self):
        for ts_file in self.src_dir.rglob('*.ts'):
            if '__tests__' not in str(ts_file):
                self.analyze_file(ts_file)
    
    def generate_report(self):
        print("=" * 80)
        print("ANÁLISE DE GARGALOS DE PERFORMANCE - BAILEYS-MOD")
        print("=" * 80)
        print()
        
        # Ordenar por severidade
        severity_order = {'CRITICAL': 0, 'HIGH': 1, 'MEDIUM': 2, 'LOW': 3}
        
        categories = [
            ('heavy_sync_loop', '🔴 CRÍTICO: Loops com Operações Pesadas Síncronas'),
            ('sync_io', '🔴 ALTO: Operações de I/O Síncronas'),
            ('json_in_loop', '🔴 ALTO: JSON.parse/stringify em Loops'),
            ('network_no_timeout', '🔴 ALTO: Operações de Rede sem Timeout'),
            ('sync_crypto', '🟡 MÉDIO: Operações de Criptografia Síncronas'),
            ('unbounded_array_ops', '🟡 MÉDIO: Operações em Arrays sem Limite'),
            ('large_buffer_alloc', '🟡 MÉDIO: Alocação de Buffers Grandes'),
            ('complex_regex', '🟢 BAIXO: Regex Complexos (ReDoS)'),
        ]
        
        total = sum(len(self.issues[cat]) for cat, _ in categories)
        print(f"Total de gargalos encontrados: {total}\n")
        
        for category, title in categories:
            items = self.issues[category]
            if items:
                print(f"\n{title}")
                print("-" * 80)
                print(f"Total: {len(items)} ocorrências\n")
                
                # Agrupar por arquivo
                by_file = defaultdict(list)
                for item in items:
                    by_file[item['file']].append(item)
                
                for file, file_items in sorted(by_file.items()):
                    print(f"  📁 {file} ({len(file_items)} ocorrências)")
                    for item in file_items[:3]:  # Mostrar apenas 3 primeiras
                        print(f"     Linha {item['line']}: {item['code'][:80]}")
                    if len(file_items) > 3:
                        print(f"     ... e mais {len(file_items) - 3} ocorrências")
                    print()
        
        return self.issues

if __name__ == '__main__':
    analyzer = PerformanceAnalyzer('/home/ubuntu/baileys-mod/src')
    analyzer.analyze_all()
    issues = analyzer.generate_report()
    
    # Salvar relatório detalhado
    with open('/home/ubuntu/baileys-mod/GARGALOS_PERFORMANCE.txt', 'w') as f:
        for category, items in issues.items():
            f.write(f"\n{'='*80}\n")
            f.write(f"{category.upper()}: {len(items)} ocorrências\n")
            f.write(f"{'='*80}\n\n")
            for item in items:
                f.write(f"Arquivo: {item['file']}\n")
                f.write(f"Linha: {item['line']}\n")
                f.write(f"Severidade: {item['severity']}\n")
                f.write(f"Código: {item['code']}\n")
                f.write("-" * 80 + "\n")
